from __future__ import annotations

from pathlib import Path
import re
from datetime import datetime
import json

from ai_chat import chat_reply


def _slugify(text: str) -> str:
    slug = re.sub(r"[^a-zA-Z0-9]+", "-", text.strip().lower()).strip("-")
    return slug or "new-project"


def _write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def create_portfolio(topic: str, root: Path | None = None) -> Path:
    base = root or (Path(__file__).parent / "generated_projects")
    folder = base / f"portfolio-{_slugify(topic)}"
    folder.mkdir(parents=True, exist_ok=True)

    html = f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{topic.title()} Portfolio</title>
  <link rel="stylesheet" href="styles.css" />
</head>
<body>
  <header>
    <h1>{topic.title()} Portfolio</h1>
    <p>Built by Jarvis on {datetime.now().strftime("%Y-%m-%d")}.</p>
  </header>
  <main>
    <section>
      <h2>About</h2>
      <p>This portfolio is focused on {topic}.</p>
    </section>
    <section>
      <h2>Projects</h2>
      <ul id="projects"></ul>
    </section>
    <section>
      <h2>Contact</h2>
      <p>Email: your-email@example.com</p>
    </section>
  </main>
  <script src="app.js"></script>
</body>
</html>
"""
    css = """body { font-family: Arial, sans-serif; margin: 0; background: #081325; color: #eaf3ff; }
header, main { max-width: 900px; margin: 0 auto; padding: 20px; }
section { background: #13233f; border-radius: 10px; padding: 16px; margin-bottom: 14px; }
h1, h2 { color: #7ed0ff; }
"""
    js = """const projects = ["Project Alpha", "Project Beta", "Project Gamma"];
const list = document.getElementById("projects");
projects.forEach((name) => {
  const li = document.createElement("li");
  li.textContent = name;
  list.appendChild(li);
});
"""
    readme = f"""# {topic.title()} Portfolio

Generated by Jarvis.

## Run
- Open `index.html` in browser.
- Edit `app.js` and `styles.css` to customize.
"""
    _write(folder / "index.html", html)
    _write(folder / "styles.css", css)
    _write(folder / "app.js", js)
    _write(folder / "README.md", readme)
    return folder


def create_python_project(topic: str, root: Path | None = None) -> Path:
    base = root or (Path(__file__).parent / "generated_projects")
    folder = base / f"project-{_slugify(topic)}"
    src = folder / "src"
    folder.mkdir(parents=True, exist_ok=True)
    src.mkdir(parents=True, exist_ok=True)

    _write(
        folder / "README.md",
        f"# {topic.title()} Project\n\nGenerated by Jarvis.\n\n## Run\n`python src/main.py`\n",
    )
    _write(folder / "requirements.txt", "")
    _write(
        src / "main.py",
        f"""def main():
    print("Welcome to {topic.title()} project")


if __name__ == "__main__":
    main()
""",
    )
    return folder


def _safe_json_load(text: str) -> dict:
    cleaned = text.strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`")
        cleaned = cleaned.replace("json", "", 1).strip()
    try:
        parsed = json.loads(cleaned)
        if isinstance(parsed, dict):
            return parsed
    except Exception:
        pass
    return {}


def _website_content(topic: str) -> dict:
    prompt = (
        f"Create premium website copy for topic '{topic}'. "
        "Return JSON with keys: title, subtitle, about, features (array of 4), cta, sections (array of 3 objects with heading and body). "
        "No markdown, only JSON."
    )
    data = _safe_json_load(chat_reply(prompt))
    if not data:
        data = {
            "title": f"{topic.title()} Studio",
            "subtitle": "Premium digital experience crafted with Jarvis.",
            "about": f"We build high-quality experiences around {topic}.",
            "features": [
                "Modern responsive design",
                "Fast performance and accessibility",
                "Clear storytelling",
                "Production-ready structure",
            ],
            "cta": "Start Your Project",
            "sections": [
                {"heading": "Vision", "body": f"Our goal is to deliver standout {topic} experiences."},
                {"heading": "Execution", "body": "We combine strategy, design, and engineering with quality standards."},
                {"heading": "Results", "body": "Clear outcomes, maintainable code, and strong user engagement."},
            ],
        }
    return data


def create_website_hq(topic: str, root: Path | None = None) -> Path:
    base = root or (Path(__file__).parent / "generated_projects")
    folder = base / f"website-{_slugify(topic)}"
    folder.mkdir(parents=True, exist_ok=True)
    content = _website_content(topic)

    title = content.get("title", f"{topic.title()} Studio")
    subtitle = content.get("subtitle", "Premium digital experience")
    about = content.get("about", f"High-quality website about {topic}.")
    features = content.get("features", [])
    while len(features) < 4:
        features.append("High-quality delivery")
    cta = content.get("cta", "Get Started")
    sections = content.get("sections", [])
    while len(sections) < 3:
        sections.append({"heading": "Section", "body": "Details coming soon."})

    html = f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{title}</title>
  <link rel="stylesheet" href="styles.css" />
</head>
<body>
  <header class="hero">
    <nav class="nav"><span class="logo">JARVIS</span><a href="#contact">Contact</a></nav>
    <h1>{title}</h1>
    <p>{subtitle}</p>
    <button>{cta}</button>
  </header>
  <main class="container">
    <section class="card"><h2>About</h2><p>{about}</p></section>
    <section class="grid">
      <article class="card"><h3>01</h3><p>{features[0]}</p></article>
      <article class="card"><h3>02</h3><p>{features[1]}</p></article>
      <article class="card"><h3>03</h3><p>{features[2]}</p></article>
      <article class="card"><h3>04</h3><p>{features[3]}</p></article>
    </section>
    <section class="card"><h2>{sections[0].get("heading","Vision")}</h2><p>{sections[0].get("body","")}</p></section>
    <section class="card"><h2>{sections[1].get("heading","Execution")}</h2><p>{sections[1].get("body","")}</p></section>
    <section class="card"><h2>{sections[2].get("heading","Results")}</h2><p>{sections[2].get("body","")}</p></section>
  </main>
  <footer id="contact">Built by Jarvis • {datetime.now().strftime("%Y")}</footer>
  <script src="app.js"></script>
</body>
</html>
"""
    css = """*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:#060b16;color:#eaf1ff}
.hero{padding:64px 24px;background:radial-gradient(circle at 10% 10%,#2563eb 0,#0b1220 55%);text-align:center}
.nav{display:flex;justify-content:space-between;max-width:980px;margin:0 auto 28px}
.logo{font-weight:700;letter-spacing:.15em}
.hero h1{font-size:clamp(2rem,6vw,4rem);margin:0}.hero p{max-width:740px;margin:12px auto 18px;color:#c7d8ff}
button{background:#22d3ee;border:none;padding:12px 20px;border-radius:999px;font-weight:700;cursor:pointer}
.container{max-width:1024px;margin:24px auto;padding:0 20px 30px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}
.card{background:#101a30;border:1px solid #263b69;border-radius:14px;padding:18px;margin-bottom:14px}
footer{text-align:center;padding:20px;color:#8ea3d1}
"""
    js = """document.querySelector("button")?.addEventListener("click",()=>alert("Thanks! Jarvis can wire this to a real contact workflow."));"""
    readme = f"""# {title}

High-quality static website generated by Jarvis.

## Run
Open `index.html` in browser.
"""
    _write(folder / "index.html", html)
    _write(folder / "styles.css", css)
    _write(folder / "app.js", js)
    _write(folder / "README.md", readme)
    return folder


def create_game_hq(topic: str, root: Path | None = None) -> Path:
    base = root or (Path(__file__).parent / "generated_projects")
    folder = base / f"game-{_slugify(topic)}"
    folder.mkdir(parents=True, exist_ok=True)

    html = f"""<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{topic.title()} Neon Runner</title>
  <link rel="stylesheet" href="styles.css" />
</head>
<body>
  <h1>{topic.title()} Neon Runner</h1>
  <p>Press Space to jump. Avoid obstacles and survive.</p>
  <canvas id="game" width="900" height="380"></canvas>
  <script src="game.js"></script>
</body>
</html>
"""
    css = """body{margin:0;padding:20px;background:#05070d;color:#e8f1ff;font-family:Arial,sans-serif;text-align:center}
canvas{border:2px solid #2dd4bf;background:#0f172a;border-radius:10px;max-width:100%}
"""
    js = """const c=document.getElementById("game"),x=c.getContext("2d");let y=300,vy=0,g=.8,j=false,s=0,b=[{x:900,w:36,h:50}];
addEventListener("keydown",e=>{if(e.code==="Space"&&!j){vy=-13;j=true;}});
function loop(){x.clearRect(0,0,c.width,c.height);x.fillStyle="#22d3ee";x.fillRect(70,y,36,50);vy+=g;y+=vy;if(y>=300){y=300;vy=0;j=false;}
b.forEach(o=>{o.x-=6;x.fillStyle="#f43f5e";x.fillRect(o.x,350-o.h,o.w,o.h);if(o.x+o.w<0){o.x=900+Math.random()*280;o.h=35+Math.random()*80;s++;}if(70<o.x+o.w&&106>o.x&&y+50>350-o.h){s=0;b=[{x:900,w:36,h:50}];}});
x.fillStyle="#e2e8f0";x.font="24px Arial";x.fillText("Score: "+s,18,34);requestAnimationFrame(loop);}loop();"""
    readme = f"""# {topic.title()} Neon Runner

Playable browser game generated by Jarvis.

## Run
Open `index.html`.
"""
    _write(folder / "index.html", html)
    _write(folder / "styles.css", css)
    _write(folder / "game.js", js)
    _write(folder / "README.md", readme)
    return folder
